// Terrain: what the painted map *means* underfoot.
//
// assets/terrain.png is a half-resolution mask of the painting (1 mask px = 2x2 map px),
// generated by tools/gen_terrain.py:
//   R = class * 40 (0 snow, 1 deep, 2 ice, 3 thin, 4 rock, 5 path), +20 if elevated
//       (a rock face just south of the point: a plateau top or ledge in the oblique view)
//   G = exposure 0..255 (open plains / plateau tops high, nooks among cliffs low)
//   B = blurred map luminance (ground.js uses it to place detail)
//
// Contract:
//   TERRAIN                -> names of terrain types
//   terrainAt(x, y)        -> TERRAIN value at a world point (map px)
//   isWalkable(x, y)       -> bool (rock and off-map are not)
//   speedFactor(type)      -> walking speed multiplier
//   shelterAt(x, y)        -> 0..1, shelter from the CURRENT wind (rock close upwind)
//   exposureAt(x, y)       -> 0..1, how open / high the ground is
//   elevatedAt(x, y)       -> bool, on a plateau top / ledge
//   findWalkable(x, y)     -> { x, y } nearest walkable point
//   ?terrain=<type> forces terrainAt() everywhere (animation testing)
import { state, MAP_W, MAP_H } from '../state.js';

export const TERRAIN = { SNOW: 'snow', DEEP: 'deep', ICE: 'ice', THIN: 'thin', ROCK: 'rock', PATH: 'path' };
export const CLASSES = [TERRAIN.SNOW, TERRAIN.DEEP, TERRAIN.ICE, TERRAIN.THIN, TERRAIN.ROCK, TERRAIN.PATH];
const ROCK = 4;

const SPEED = { snow: 1, deep: 0.45, ice: 1.15, thin: 0.9, path: 1.3, rock: 0 };

export const MASK_SCALE = 2;          // map px per mask px
let MW = 0, MH = 0;
let cls = null;                       // Uint8Array, class index per mask px
let expo = null;                      // Uint8Array, exposure 0..255
let lum = null;                       // Uint8Array, map luminance 0..255
let elev = null;                      // Uint8Array, 1 = plateau top / ledge
// Coarse rock occupancy for shelter rays: 1 cell = 8 map px, value = rock fraction 0..255.
const CELL = 8;
let CW = 0, CH = 0, coarse = null;

const forced = state.params.get('terrain');
let ready = false;

export function init() {
  return new Promise(res => {
    const img = new Image();
    img.onload = () => {
      try { build(img); } catch (e) { console.error('[terrain] mask failed:', e); }
      res();
    };
    img.onerror = () => { console.error('[terrain] could not load assets/terrain.png'); res(); };
    img.src = 'assets/terrain.png';
  });
}

function build(img) {
  MW = img.width; MH = img.height;
  let c = document.createElement('canvas');
  c.width = MW; c.height = MH;
  const g = c.getContext('2d', { willReadFrequently: true });
  g.drawImage(img, 0, 0);
  const d = g.getImageData(0, 0, MW, MH).data;
  c.width = c.height = 0; c = null; // let the canvas go
  const n = MW * MH;
  cls = new Uint8Array(n); expo = new Uint8Array(n); lum = new Uint8Array(n); elev = new Uint8Array(n);
  for (let i = 0, j = 0; i < n; i++, j += 4) {
    cls[i] = Math.min(5, Math.floor((d[j] + 5) / 40));
    elev[i] = d[j] % 40 >= 10 ? 1 : 0;
    expo[i] = d[j + 1];
    lum[i] = d[j + 2];
  }
  // Coarse rock grid.
  const k = CELL / MASK_SCALE;
  CW = Math.ceil(MW / k); CH = Math.ceil(MH / k);
  coarse = new Uint8Array(CW * CH);
  const cnt = new Uint16Array(CW * CH);
  for (let y = 0; y < MH; y++) {
    const cy = (y / k) | 0;
    for (let x = 0; x < MW; x++) {
      const ci = cy * CW + ((x / k) | 0);
      if (cls[y * MW + x] === ROCK) cnt[ci]++;
    }
  }
  for (let i = 0; i < cnt.length; i++) coarse[i] = Math.min(255, Math.round((cnt[i] / (k * k)) * 255));
  ready = true;
}

function idx(x, y) {
  const mx = Math.floor(x / MASK_SCALE), my = Math.floor(y / MASK_SCALE);
  if (mx < 0 || my < 0 || mx >= MW || my >= MH) return -1;
  return my * MW + mx;
}

/** Class index (0..5) at a world point; off-map is rock. Ignores ?terrain. */
export function classAt(x, y) {
  if (!ready) return 0;
  const i = idx(x, y);
  return i < 0 ? ROCK : cls[i];
}

export function terrainAt(x, y) {
  if (forced) return forced;
  return CLASSES[classAt(x, y)];
}

export function isWalkable(x, y) {
  if (!ready) return true;
  return classAt(x, y) !== ROCK;
}

export function speedFactor(type) {
  return SPEED[type] ?? 1;
}

/** Map luminance (0..255, blurred) at a world point; for detail placement. */
export function lumAt(x, y) {
  if (!ready) return 240;
  const i = idx(x, y);
  return i < 0 ? 240 : lum[i];
}

/** True on plateau tops and ledges (a rock face just south of the point). */
export function elevatedAt(x, y) {
  if (!ready) return false;
  const i = idx(x, y);
  return i >= 0 && elev[i] === 1;
}

export function exposureAt(x, y) {
  if (!ready) return 0.5;
  const i = idx(x, y);
  return i < 0 ? 1 : expo[i] / 255;
}

function rockFrac(x, y) {
  const cx = Math.floor(x / CELL), cy = Math.floor(y / CELL);
  if (cx < 0 || cy < 0 || cx >= CW || cy >= CH) return 1; // off-map is rock, as in classAt
  return coarse[cy * CW + cx] / 255;
}

// Shelter: cast three short rays upwind (the wind blows TOWARD state.wind.angle, so
// upwind is the opposite way). Rock close upwind shelters strongly; rock further off,
// or only a thin pinnacle, shelters less. On a plateau top / ledge, rock to the south
// is that plateau's own cliff face dropping away below us, so it gives no shelter.
const SHELTER_REACH = 90;   // world px
const SHELTER_STEP = 6;
export function shelterAt(x, y) {
  if (!ready) return 0;
  if (classAt(x, y) === ROCK) return 1;
  const a = state.wind.angle + Math.PI;
  const high = elevatedAt(x, y);
  let total = 0;
  for (const off of [-0.3, 0, 0.3]) {
    const dx = Math.cos(a + off), dy = Math.sin(a + off);
    let s = 0, mass = 0;
    for (let d = SHELTER_STEP; d <= SHELTER_REACH; d += SHELTER_STEP) {
      if (high && dy * d > 2) break; // ray heads down our own cliff face
      const f = rockFrac(x + dx * d, y + dy * d);
      if (f > 0) {
        mass += f * SHELTER_STEP;
        const near = 1 - d / (SHELTER_REACH + SHELTER_STEP);
        s = Math.max(s, near * Math.min(1, mass / 18));
      }
    }
    total += s * (off === 0 ? 0.5 : 0.25);
  }
  return Math.min(1, total * 1.15);
}

/** Nearest walkable point (searches outward in rings, up to ~300 world px). Every
 *  walkable mask pixel is reachable from the spawn: unreachable pockets are baked in
 *  as rock by tools/gen_terrain.py, so the result is never a sealed-off pocket. */
export function findWalkable(x, y) {
  if (!ready || isWalkable(x, y)) return { x, y };
  const mx = Math.floor(x / MASK_SCALE), my = Math.floor(y / MASK_SCALE);
  for (let r = 1; r <= 150; r++) {
    let best = null, bd = Infinity;
    for (let dy = -r; dy <= r; dy++) {
      for (let dx = -r; dx <= r; dx++) {
        if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
        const px = mx + dx, py = my + dy;
        if (px < 0 || py < 0 || px >= MW || py >= MH) continue;
        if (cls[py * MW + px] === ROCK) continue;
        const dd = dx * dx + dy * dy;
        if (dd < bd) { bd = dd; best = [px, py]; }
      }
    }
    if (best) return { x: (best[0] + 0.5) * MASK_SCALE, y: (best[1] + 0.5) * MASK_SCALE };
  }
  return { x: Math.min(MAP_W - 1, Math.max(0, x)), y: Math.min(MAP_H - 1, Math.max(0, y)) };
}

/** Raw mask access for ground.js (debug overlay, detail placement). */
export function mask() {
  return ready ? { cls, expo, lum, elev, w: MW, h: MH, scale: MASK_SCALE } : null;
}
